import json
import time
import boto3
from botocore.config import Config

def chunk(lst, n):
  for i in range(0, len(lst), n):
      yield lst[i : i + n]

def find_managed_instances(ssm_client, instance_ids):
    """Given a list of instance_ids, returns the subset of the input which are managed"""
    managed_set = set()
    for instance_chunk in chunk(instance_ids, 100):
        page_iterator = ssm_client.get_paginator("describe_instance_information").paginate(
            Filters=[
                {"Key": "InstanceIds", "Values": instance_chunk},
                {"Key": "PingStatus", "Values": ["Online"]}
            ]
        )
        for page in page_iterator:
            for instance in page["InstanceInformationList"]:
                managed_set.add(instance["InstanceId"])
    return managed_set


def get_instance_page(ec2_client, next_token, MaxResults=1000):
    """Returns a dict with the instance_id as key, and the value is the minimal instance object we need for diagnosis"""

    filters = [{"Name": "instance-state-name", "Values": ["running", "stopping", "stopped"]}]
    kwargs = {
        "Filters": filters,
        "MaxResults": MaxResults
    }
    if next_token:
        kwargs["NextToken"] = next_token

    result = ec2_client.describe_instances(**kwargs)

    instances = []
    for reservation in result.get("Reservations", []):
        for instance in reservation.get("Instances", []):
            instances.append(instance["InstanceId"])
    return instances, result.get("NextToken", None)

def find_unmanaged_instances(ssm_client, instances):
    unmanaged_instances = []
    managed_instances = find_managed_instances(ssm_client, instances)
    for instance_id in instances:
        if instance_id not in managed_instances:
            unmanaged_instances.append(instance_id)
    return unmanaged_instances

def handler(event, context):
    start_time = time.time()

    # required parameters
    instance_next_token = event.get("InstanceNextToken", None)
    unmanaged_node_count = event.get("UnmanagedNodeCount", 0)

    # optional parameters
    timeout_seconds = event.get("TimeoutSeconds", 540)
    describe_instances_page_size = event.get("DescribeInstancesPageSize", 1000)

    # clients
    config = Config(retries={"max_attempts": 5, "mode": "standard"})
    ec2_client = boto3.client("ec2", config=config)
    ssm_client = boto3.client("ssm", config=config)

    first_run = True
    while instance_next_token or first_run:
        first_run = False

        instances, _next_token = get_instance_page(ec2_client, instance_next_token, MaxResults=describe_instances_page_size)
        unmanaged_instances = find_unmanaged_instances(ssm_client, instances)
        unmanaged_node_count += len(unmanaged_instances)
        instance_next_token = _next_token

        if time.time() - start_time > timeout_seconds:
            break

    return {
        "InstanceNextToken": instance_next_token,
        "ShouldContinue": bool(instance_next_token),
        "UnmanagedNodeCount": unmanaged_node_count
    }
